// Generated by ChatGPT to compare simple Bisection with secant for simple
// Regula Falsi
//
// vs.
//
// Modified Regula Falsi that converges from two sides using the secant and the slope of the function where the secant
// intersects the X axis.
/*
 * root_methods_compare.c
 *
 * Direct comparison of:
 *   1. Simple secant method
 *   2. Regula falsi (false-position) method
 *   3. Illinois modified regula falsi method
 *
 * Compile:
 *   cc -std=c99 -Wall -Wextra -O2 root_methods_compare.c -lm -o root_methods_compare
 *
 * All methods use a callback of the form double f(double x).
 * To solve a different problem, replace example_function() and choose
 * suitable starting values in main().
 */

#include <float.h>
#include <math.h>
#include <stdio.h>

typedef double (*Function)(double x);

typedef struct {
    double root;
    double f_root;
    int iterations;
    int evaluations;
    int converged;
} RootResult;

static int is_finite_number(double x)
{
    return isfinite(x);
}

static int close_enough(double x, double x_old, double fx, double x_tol,
                        double f_tol)
{
    return fabs(x - x_old) <= x_tol * (1.0 + fabs(x)) || fabs(fx) <= f_tol;
}

static RootResult make_failure(double x, double fx, int evaluations)
{
    RootResult result = {x, fx, 0, evaluations, 0};
    return result;
}

/*
 * Simple secant method.
 * Unlike regula falsi, secant does not preserve a sign-changing bracket.
 */
static RootResult secant(Function f, double x0, double x1, int max_iter,
                         double x_tol, double f_tol)
{
    double f0 = f(x0);
    double f1 = f(x1);
    int evaluations = 2;

    if (!is_finite_number(f0) || !is_finite_number(f1))
        return make_failure(x1, f1, evaluations);
    if (fabs(f0) <= f_tol)
        return (RootResult){x0, f0, 0, evaluations, 1};
    if (fabs(f1) <= f_tol)
        return (RootResult){x1, f1, 0, evaluations, 1};

    for (int iteration = 1; iteration <= max_iter; ++iteration) {
        double denominator = f1 - f0;
        if (fabs(denominator) <= DBL_EPSILON * (1.0 + fabs(f1) + fabs(f0)))
            return (RootResult){x1, f1, iteration - 1, evaluations, 0};

        double x2 = x1 - f1 * (x1 - x0) / denominator;
        if (!is_finite_number(x2))
            return (RootResult){x1, f1, iteration - 1, evaluations, 0};

        double f2 = f(x2);
        ++evaluations;
        if (!is_finite_number(f2))
            return (RootResult){x2, f2, iteration, evaluations, 0};

        if (close_enough(x2, x1, f2, x_tol, f_tol))
            return (RootResult){x2, f2, iteration, evaluations, 1};

        x0 = x1;
        f0 = f1;
        x1 = x2;
        f1 = f2;
    }

    return (RootResult){x1, f1, max_iter, evaluations, 0};
}

/*
 * Standard regula falsi.
 * The sign-changing bracket [a,b] is preserved at every iteration.
 */
static RootResult regula_falsi(Function f, double a, double b, int max_iter,
                               double x_tol, double f_tol)
{
    double fa = f(a);
    double fb = f(b);
    int evaluations = 2;

    if (!is_finite_number(fa) || !is_finite_number(fb))
        return make_failure(b, fb, evaluations);
    if (fabs(fa) <= f_tol)
        return (RootResult){a, fa, 0, evaluations, 1};
    if (fabs(fb) <= f_tol)
        return (RootResult){b, fb, 0, evaluations, 1};
    if (fa * fb > 0.0)
        return make_failure(b, fb, evaluations);

    double x = b;
    double fx = fb;

    for (int iteration = 1; iteration <= max_iter; ++iteration) {
        double denominator = fb - fa;
        if (fabs(denominator) <= DBL_EPSILON * (1.0 + fabs(fa) + fabs(fb)))
            return (RootResult){x, fx, iteration - 1, evaluations, 0};

        double old_x = x;
        x = (a * fb - b * fa) / denominator;
        if (!is_finite_number(x))
            return (RootResult){old_x, fx, iteration - 1, evaluations, 0};

        fx = f(x);
        ++evaluations;
        if (!is_finite_number(fx))
            return (RootResult){x, fx, iteration, evaluations, 0};

        if (close_enough(x, old_x, fx, x_tol, f_tol))
            return (RootResult){x, fx, iteration, evaluations, 1};

        if (fa * fx < 0.0) {
            b = x;
            fb = fx;
        } else {
            a = x;
            fa = fx;
        }
    }

    return (RootResult){x, fx, max_iter, evaluations, 0};
}

/*
 * Illinois modified regula falsi.
 * When the same endpoint survives two consecutive updates, its function
 * value is divided by two. This prevents the endpoint from becoming stuck
 * and usually makes the method substantially faster than standard regula
 * falsi while retaining a sign-changing bracket.
 */
static RootResult modified_regula_falsi(Function f, double a, double b,
                                        int max_iter, double x_tol,
                                        double f_tol)
{
    double fa = f(a);
    double fb = f(b);
    int evaluations = 2;

    if (!is_finite_number(fa) || !is_finite_number(fb))
        return make_failure(b, fb, evaluations);
    if (fabs(fa) <= f_tol)
        return (RootResult){a, fa, 0, evaluations, 1};
    if (fabs(fb) <= f_tol)
        return (RootResult){b, fb, 0, evaluations, 1};
    if (fa * fb > 0.0)
        return make_failure(b, fb, evaluations);

    double x = b;
    double fx = fb;
    int last_replaced = 0; /* -1: a replaced, +1: b replaced, 0: neither */

    for (int iteration = 1; iteration <= max_iter; ++iteration) {
        double denominator = fb - fa;
        if (fabs(denominator) <= DBL_EPSILON * (1.0 + fabs(fa) + fabs(fb)))
            return (RootResult){x, fx, iteration - 1, evaluations, 0};

        double old_x = x;
        x = (a * fb - b * fa) / denominator;
        if (!is_finite_number(x))
            return (RootResult){old_x, fx, iteration - 1, evaluations, 0};

        fx = f(x);
        ++evaluations;
        if (!is_finite_number(fx))
            return (RootResult){x, fx, iteration, evaluations, 0};

        if (close_enough(x, old_x, fx, x_tol, f_tol))
            return (RootResult){x, fx, iteration, evaluations, 1};

        if (fa * fx < 0.0) {
            b = x;
            fb = fx;
            if (last_replaced == 1)
                fa *= 0.5;
            last_replaced = 1;
        } else {
            a = x;
            fa = fx;
            if (last_replaced == -1)
                fb *= 0.5;
            last_replaced = -1;
        }
    }

    return (RootResult){x, fx, max_iter, evaluations, 0};
}

/* Replace this function with any continuous function whose root is desired. */
static double example_function(double x)
{
    // As can be seen with Desmos, this example equation has roots near: -2.851, 4.758, and 7.792
    return (-(x*x*x) + 9.7*(x*x) -1.3*x -105.7);

    //return x * x * x - x - 2.0; /* root near x = 1.5213797068 */
}

static void print_result(const char *name, RootResult result)
{
    printf("%-28s root = % .12f, f(root) = % .3e, "
           "iterations = %4d, evaluations = %4d, %s\n",
           name, result.root, result.f_root, result.iterations,
           result.evaluations, result.converged ? "CONVERGED" : "FAILED");
}

int main(void)
{
    /* The bracket [1, 2] has opposite signs for x^3 - x - 2. */
    const double a = -3.0;
    const double b = 3.0;
    const int max_iter = 1000000;
    const double x_tol = 1.0e-12;
    const double f_tol = 1.0e-12;

    printf("Function: f(x) = x^3 - x - 2\n");
    printf("Interval: [%.6f, %.6f]\n\n", a, b);
    printf("A sign-changing bracket is required by the two regula falsi methods.\n");
    printf("The secant method uses the same endpoints as its two initial guesses.\n\n");

    print_result("Simple secant", secant(example_function, a, b, max_iter,
                                         x_tol, f_tol));
    print_result("Regula falsi", regula_falsi(example_function, a, b,
                                               max_iter, x_tol, f_tol));
    print_result("Modified regula falsi (Illinois)",
                 modified_regula_falsi(example_function, a, b, max_iter,
                                       x_tol, f_tol));

    return 0;
}
